class Solution:
    def minimumDeviation(self, nums):
        candidates = []
        for idx, num in enumerate(nums):
            value = num * 2 if num % 2 else num
            seen = set()
            while True:
                seen.add(value)
                if value % 2:
                    break
                value //= 2
            for value in seen:
                candidates.append((value, idx))
        candidates.sort()
        need = len(nums)
        counts = [0] * need
        covered = 0
        left = 0
        best = candidates[-1][0] - candidates[0][0]
        for right, (value, idx) in enumerate(candidates):
            if counts[idx] == 0:
                covered += 1
            counts[idx] += 1
            while covered == need:
                best = min(best, value - candidates[left][0])
                left_idx = candidates[left][1]
                counts[left_idx] -= 1
                if counts[left_idx] == 0:
                    covered -= 1
                left += 1
        return best

